<?php require __DIR__.'/_nav.php';use OCP\IURLGenerator;$url=\OC::$server->get(IURLGenerator::class);\OCP\Util::addScript('reinhardterp','orders');?>
<div id="app-content"><div class="erp-page erp-orders-premium"><div class="erp-head"><div><span class="erp-eyebrow">VERKAUF</span><h1>Aufträge</h1><p class="erp-sub">Aus angenommenen Angeboten erzeugte Aufträge.</p></div></div><div class="erp-card erp-document-list-card"><div class="erp-section-head"><div><h2>Auftragsübersicht</h2><p class="erp-muted">Alle übernommenen Kundenaufträge im Überblick.</p></div></div><div class="erp-document-filter"><input id="orderSearch" type="search" placeholder="Suchen …"><select id="orderYear" aria-label="Jahr"><option value="">Alle Jahre</option><?php $orderYears=[date('Y')=>true];foreach($_['orders'] as $row){$y=substr((string)($row['order_date']??''),0,4);if($y!=='')$orderYears[$y]=true;}krsort($orderYears);foreach(array_keys($orderYears) as $y):?><option value="<?php p($y);?>" <?php if((string)$y===date('Y'))p('selected');?>><?php p($y);?></option><?php endforeach;?></select><button class="button" id="orderShowAll" type="button">Alle anzeigen</button></div><div class="erp-table"><table><thead><tr><th>Nummer</th><th>Datum</th><th>Kunde</th><th>Titel</th><th>Status</th><th>Netto</th><th>Brutto</th></tr></thead><tbody data-betrio-auto-page="25"><?php foreach($_['orders'] as $o):?><tr data-order-row data-year="<?php p(substr((string)($o['order_date']??''),0,4));?>" data-search="<?php p(strtolower(($o['order_no']??'').' '.($o['customer_name']??'').' '.($o['title']??'')));?>"><td><a href="<?php p($url->linkToRoute('reinhardterp.business.orderDetail',['id'=>$o['id']]));?>"><strong><?php p($o['order_no']);?></strong></a></td><td><?php p(date('d.m.Y',strtotime($o['order_date'])));?></td><td><?php p($o['customer_name']);?></td><td><?php p($o['title']);?></td><td><span class="erp-badge"><?php p($o['status']);?></span></td><td><?php p(number_format((float)$o['net_amount'],2,',','.').' €');?></td><td><?php p(number_format((float)$o['gross_amount'],2,',','.').' €');?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>